// Typed request bindings for the module specifications.
//
// Each binding selects a stable Rust ID, a module/ordinal, semantic parameter
// layout and result shape. Export names, calling conventions and encoded slot
// widths come from the module specifications generated at build time.

macro_rules! export_catalog {
    (
        $(
            $(#[$meta:meta])*
            $variant:ident => $constant:ident: (
                $module:literal, $ordinal:literal,
                $abi_kind:ident, $parameters:expr, $return_kind:ident
            );
        )+
    ) => {
        #[derive(Clone, Copy, Debug, Eq, PartialEq, Hash)]
        pub enum Win16ExportId { $($variant,)+ }
        impl Win16ExportId {
            pub const fn module(self) -> &'static str { match self { $(Self::$variant => $module,)+ } }
            pub const fn ordinal(self) -> u16 { match self { $(Self::$variant => $ordinal,)+ } }
            pub const fn name(self) -> &'static str { match self {
                $(Self::$variant => declarations::export_name($module, $ordinal),)+
            } }
        }
        $(
            $(#[$meta])*
            pub const $constant: Win16ExportDescriptor = Win16ExportDescriptor {
                id: Win16ExportId::$variant,
                abi_kind: Win16ExportAbiKind::$abi_kind,
                parameters: declarations::checked_parameters(
                    $module, $ordinal, Win16ExportAbiKind::$abi_kind, $parameters),
                calling_convention: declarations::calling_convention($module, $ordinal),
                return_kind: Win16ReturnKind::$return_kind,
                stack_cleanup: stack_cleanup_for(
                    $parameters,
                    Win16ExportAbiKind::$abi_kind,
                    declarations::calling_convention($module, $ordinal),
                ),
            };
        )+
        const EXPORTS: &[Win16ExportDescriptor] = &[$($constant,)+];
    };
}

